// Preserve the exhaustive UUID ranges generated by readUuidPages. The RPC
// applies the caller's RLS and selects the same compact fields as the first page.
import {ORGANIZATION_ID} from './supabase-config.mjs';
export function readSalesPage(read,path){
 const params=new URL(path,'http://workspace.local').searchParams;
 const bounds={p_organization_id:ORGANIZATION_ID,p_limit:Number(params.get('limit'))};
 for(const filter of params.getAll('id')){
  const [op,value]=filter.split('.');
  if(op==='gt')bounds.p_after=bounds.p_after&&bounds.p_after>value?bounds.p_after:value;
  else if(op==='gte')bounds.p_lower=value;
  else if(op==='lt')bounds.p_upper=value;
  else throw Error('Invalid sales page filter.');
 }
 return read('/rest/v1/rpc/workspace_sales_page',{method:'POST',body:bounds});
}
